import React, { useState } from 'react'
import { Modal } from 'antd';
import { Document, Page, pdfjs } from 'react-pdf';

function ViewContractPDFModal({ openPDFModal, setopenPDFModal, contractUrl }) {
    //     pdfjs.GlobalWorkerOptions.workerSrc = new URL(
    //         'https://unpkg.com/pdfjs-dist@3.11.174/build/pdf.worker.min.js',
    //   import.meta.url,
    // ).toString();
    // pdfjs.GlobalWorkerOptions.workerSrc = `//unpkg.com/pdfjs-dist@${pdfjs.version}/build/pdf.worker.min.js`;

    pdfjs.GlobalWorkerOptions.workerSrc = new URL(
        'pdfjs-dist/build/pdf.worker.min.mjs',
        import.meta.url,
    ).toString()
    const [numPages, setNumPages] = useState(null);
    const [pageNumber, setPageNumber] = useState(1);

    /*To Prevent right click on screen*/
    document.addEventListener("contextmenu", (event) => {
        event.preventDefault();
    });

    /*When document gets loaded successfully*/
    function onDocumentLoadSuccess({ numPages }) {
        setNumPages(numPages);
        setPageNumber(1);
    }

    function changePage(offset) {
        setPageNumber(prevPageNumber => prevPageNumber + offset);
    }

    function previousPage() {
        changePage(-1);
    }

    function nextPage() {
        changePage(1);
    }

    return (
        <Modal
            className="overflow-y-scroll max-h-lvh"
            open={openPDFModal}
            title="View Contract PDF"
            footer={null}
            width={800}
            style={{ height: 600, top: 20, padding: 0, position: 'relative' }}
            destroyOnClose
            onClose={() => setopenPDFModal(false)}
            onCancel={() => setopenPDFModal(false)}
        >
            <>
                <div
                    id="container"
                    className="w-full h-[520px] overflow-y-auto overflow-x-hidden flex flex-col items-center justify-start"
                >
                    <Document
                        file={contractUrl}
                        onLoadSuccess={onDocumentLoadSuccess}
                        className="w-full flex justify-center"
                    >
                        <Page pageNumber={pageNumber} />
                    </Document>
                </div>
                <div>
                    <div className="pagec text-center my-2">
                        Page {pageNumber || (numPages ? 1 : '--')} of {numPages || '--'}
                    </div>
                    <div className="buttonc flex justify-center gap-4">
                        <button
                            type="button"
                            disabled={pageNumber <= 1}
                            onClick={previousPage}
                            className="Pre px-4 py-2 bg-gray-200 rounded disabled:opacity-50"
                        >
                            Previous
                        </button>
                        <button
                            type="button"
                            disabled={pageNumber >= numPages}
                            onClick={nextPage}
                            className="px-4 py-2 bg-gray-200 rounded disabled:opacity-50"
                        >
                            Next
                        </button>
                    </div>
                </div>
            </>
        </Modal>
    )
}

export default ViewContractPDFModal